package app.p3r.dayplanner.v2;

import org.json.*;
import org.junit.*;
import org.junit.runner.RunWith;
import org.robolectric.RobolectricTestRunner;
import org.robolectric.RuntimeEnvironment;
import org.robolectric.annotation.Config;
import static org.junit.Assert.*;

/** Executable adapter checks only; not game-replay or full-goal completeness claims. */
@RunWith(RobolectricTestRunner.class) @Config(sdk=28)
public class NativeUnlockRulesTest {
    private static NativeUnlockRules cached;
    private NativeUnlockRules adapter()throws Exception{if(cached==null)cached=new NativeUnlockRules(RuntimeEnvironment.getApplication());return cached;}
    private JSONObject o(String value)throws Exception{return new JSONObject(value);}
    private JSONObject interval(int value)throws Exception{return new JSONObject().put("low",value).put("high",value);}
    private JSONObject state(String slug,int month,int day,boolean night)throws Exception{return new JSONObject().put("run_id","unlock-fixture").put("revision",4).put("rules_version",adapter().version).put("game_slot",GameDate.slot(month,day,night)).put("cash",40000).put("visits_by_stage",o("{\"p3r.tower.stage_07\":null}")).put("facts",new JSONObject().put("socialLinks."+slug+".rank",interval(0)));}
    private JSONObject context(JSONObject state)throws Exception {int slot=state.getInt("game_slot");return new JSONObject().put("gameEdition","P3R-base").put("checkpoint",new JSONObject().put("consistencyValidated",true).put("date",new JSONObject().put("ordinal",slot/2))).put("calendar",new JSONObject().put("slotStates",new JSONObject().put(""+slot,o("{\"remainingCapacity\":1,\"knownStoryLock\":false,\"slotState\":\"free\"}"))));}
    private JSONObject build(JSONObject state,JSONObject context)throws Exception{return adapter().build(state,context,new JSONObject());}
    private JSONObject action(JSONObject built,String id)throws Exception {JSONArray actions=built.getJSONObject("rules").getJSONArray("actions");for(int i=0;i<actions.length();i++)if(id.equals(actions.getJSONObject(i).getString("id")))return actions.getJSONObject(i);return null;}
    private boolean hasSlot(JSONObject action,int slot)throws Exception {if(action==null)return false;JSONArray slots=action.getJSONArray("slots");for(int i=0;i<slots.length();i++)if(slots.getInt(i)==slot)return true;return false;}
    private void prep(JSONObject context,String slug,String stage)throws Exception{JSONObject unlock=context.optJSONObject("unlock");if(unlock==null){unlock=new JSONObject();context.put("unlock",unlock);}unlock.put(slug,new JSONObject().put("stage",stage));}
    private void exactGuards(JSONObject context,int slot,String source,JSONObject guards)throws Exception {JSONObject calendar=context.getJSONObject("calendar"),states=calendar.optJSONObject("unlockActionStates");if(states==null){states=new JSONObject();calendar.put("unlockActionStates",states);}JSONObject at=states.optJSONObject(""+slot);if(at==null){at=new JSONObject();states.put(""+slot,at);}at.put(source,guards);}
    private boolean check(JSONObject built,String code)throws Exception{JSONArray checks=built.getJSONArray("observation_checkpoints");for(int i=0;i<checks.length();i++)if(code.equals(checks.getJSONObject(i).optString("kind")))return true;return false;}

    @Test public void directIntroductionConsumesOneSlotWithoutInventedAffinity()throws Exception {
        JSONObject state=state("emperor",4,27,false),context=context(state);String before=state.toString();JSONObject built=build(state,context),action=action(built,"p3r.unlock.emperor");assertTrue(hasSlot(action,state.getInt("game_slot")));assertTrue(action.getBoolean("strict_requirements"));
        JSONObject result=PlannerEngine.transition(built.getJSONObject("rules"),built.getJSONObject("engine_snapshot"),action,new JSONObject()).getJSONObject("state");assertEquals(state.getInt("game_slot")+1,result.getInt("slot"));assertEquals(1,result.getJSONObject("values").getJSONObject("socialLinks.emperor.rank").getInt("low"));assertTrue(result.getJSONObject("values").getJSONObject("socialLinks.emperor.affinityLowerBound").isNull("high"));assertEquals(before,state.toString());assertTrue(built.getJSONObject("engine_snapshot").getJSONObject("visits").isNull("p3r.tower.stage_07"));
    }
    @Test public void allElevenSimpleLinksHaveAuditedModelsAndDependencies()throws Exception{JSONObject state=state("priestess",6,19,false),built=build(state,context(state));assertEquals(18,built.getJSONArray("supported_goal_fields").length());JSONArray deps=built.getJSONObject("goal_dependencies").getJSONArray("socialLinks.priestess.rank");assertEquals(2,deps.length());assertTrue(deps.toString().contains("socialStats.courage.raw"));assertTrue(deps.toString().contains("socialLinks.fortune.rank"));}
    @Test public void prerequisiteTrainingRemainsRuntimeRawGuard()throws Exception {JSONObject state=state("priestess",6,19,false);state.getJSONObject("facts").put("socialStats.courage.rank",interval(5)).put("socialLinks.fortune.rank",interval(1));JSONObject built=build(state,context(state)),action=action(built,"p3r.unlock.priestess");assertNotNull(action);assertEquals(80,action.getJSONObject("requirements").getInt("socialStats.courage.raw"));assertEquals(60,built.getJSONObject("engine_snapshot").getJSONObject("values").getJSONObject("socialStats.courage.raw").getInt("low"));}
    @Test public void exactRankSixDerivesBoundNotExactHiddenValue()throws Exception{JSONObject state=state("lovers",7,25,false);state.getJSONObject("facts").put("socialStats.charm.rank",interval(6));JSONObject built=build(state,context(state)),raw=built.getJSONObject("engine_snapshot").getJSONObject("values").getJSONObject("socialStats.charm.raw");assertEquals(100,raw.getInt("low"));assertTrue(raw.isNull("high"));assertNotNull(action(built,"p3r.unlock.lovers"));}
    @Test public void unknownInventoryNeverInventsOnlineGame()throws Exception{JSONObject state=state("hermit",4,29,false),context=context(state);assertNull(action(build(state,context),"p3r.unlock.hermit"));context.put("unlock",o("{\"hermit\":{\"observations\":{\"inventory.onlineGameAvailable\":true}}}"));assertNotNull(action(build(state,context),"p3r.unlock.hermit"));}
    @Test public void empressConflictNeedsObservedOpeningOrExplicitPolicy()throws Exception{JSONObject state=state("empress",11,21,false),context=context(state);state.getJSONObject("facts").put("socialStats.academics.rank",interval(6));assertNull(action(build(state,context),"p3r.unlock.empress"));JSONObject assumed=adapter().build(state,context,o("{\"unlock_assumptions\":{\"empress_wiki_first_gate\":true}}"));assertNotNull(action(assumed,"p3r.unlock.empress"));exactGuards(context,state.getInt("game_slot"),"p3r.unlock.empress",o("{\"observedIntroductionAvailable\":true}"));JSONObject current=action(build(state,context),"p3r.unlock.empress");assertTrue(hasSlot(current,state.getInt("game_slot")));assertEquals(1,current.getJSONArray("slots").length());}
    @Test public void observedEarlierIntroductionDoesNotWaiveOtherPrerequisites()throws Exception{JSONObject state=state("priestess",6,18,false),context=context(state);exactGuards(context,state.getInt("game_slot"),"p3r.unlock.priestess",o("{\"observedIntroductionAvailable\":true}"));JSONObject action=action(build(state,context),"p3r.unlock.priestess");assertTrue(hasSlot(action,state.getInt("game_slot")));assertEquals(80,action.getJSONObject("requirements").getInt("socialStats.courage.raw"));assertEquals(1,action.getJSONObject("requirements").getInt("socialLinks.fortune.rank"));}
    @Test public void currentFalseObservationAndStoryLockOverrideSourceDate()throws Exception {JSONObject state=state("emperor",4,27,false),context=context(state);exactGuards(context,state.getInt("game_slot"),"p3r.unlock.emperor",o("{\"observedIntroductionAvailable\":false}"));assertFalse(hasSlot(action(build(state,context),"p3r.unlock.emperor"),state.getInt("game_slot")));context=context(state);context.getJSONObject("calendar").getJSONObject("slotStates").getJSONObject(""+state.getInt("game_slot")).put("knownStoryLock",true);assertFalse(hasSlot(action(build(state,context),"p3r.unlock.emperor"),state.getInt("game_slot")));}
    @Test public void noUnobservedPreparationResetOrPayment()throws Exception {JSONObject state=state("devil",7,25,true),built=build(state,context(state));assertEquals(0,built.getJSONObject("rules").getJSONArray("actions").length());assertTrue(check(built,"preparation_state_unknown"));assertFalse(built.getJSONObject("engine_snapshot").getJSONObject("values").has("unlock.devil.stageCode"));}
    @Test public void zeroSlotPaymentPreservedAsCheckpointNotOneSlotAction()throws Exception {JSONObject state=state("devil",6,6,true),context=context(state);prep(context,"devil","unstarted");JSONObject built=build(state,context);assertNull(action(built,"p3r.unlock.devil.payment1"));JSONArray checks=built.getJSONArray("observation_checkpoints");boolean found=false;for(int i=0;i<checks.length();i++){JSONObject c=checks.getJSONObject(i);if("p3r.unlock.devil.payment1".equals(c.optString("source_rule_id"))){found=true;assertEquals(0,c.getInt("source_slot_cost"));assertEquals(20000,c.getInt("money_cost_jpy"));}}assertTrue(found);assertEquals(40000,built.getJSONObject("engine_snapshot").getJSONObject("values").getJSONObject("cash").getInt("low"));}
    @Test public void knownPriorPaymentUnknownDateRequiresNextDistinctDay()throws Exception{JSONObject state=state("devil",7,24,true),context=context(state);prep(context,"devil","paid2");int start=state.getInt("game_slot"),next=start+2;exactGuards(context,start,"p3r.unlock.devil.payment3",o("{\"current.devil.payment_interaction_available\":true}"));exactGuards(context,next,"p3r.unlock.devil.payment3",o("{\"current.devil.payment_interaction_available\":true}"));JSONObject built=build(state,context),action=action(built,"p3r.unlock.devil.payment3");assertNotNull(action);assertFalse(hasSlot(action,start));assertTrue(hasSlot(action,next));assertEquals(10000,action.getJSONObject("costs").getInt("cash"));assertNull(action(built,"p3r.unlock.devil.payment1"));assertNull(action(built,"p3r.unlock.devil.payment2"));}
    @Test public void finalPaymentChargesOnlyRemainingTenThousand()throws Exception{JSONObject state=state("devil",7,25,true),context=context(state);prep(context,"devil","paid2");context.getJSONObject("unlock").getJSONObject("devil").put("lastPaymentDate",state.getInt("game_slot")/2-1);exactGuards(context,state.getInt("game_slot"),"p3r.unlock.devil.payment3",o("{\"current.devil.payment_interaction_available\":true}"));JSONObject built=build(state,context),action=action(built,"p3r.unlock.devil.payment3");assertNotNull(action);JSONObject result=PlannerEngine.transition(built.getJSONObject("rules"),built.getJSONObject("engine_snapshot"),action,new JSONObject()).getJSONObject("state");assertEquals(30000,result.getJSONObject("values").getJSONObject("cash").getInt("low"));assertEquals(1,result.getJSONObject("values").getJSONObject("socialLinks.devil.rank").getInt("low"));}
    @Test public void foodAlreadyGivenNeverConsumedAgain()throws Exception{JSONObject state=state("hanged_man",5,11,false),context=context(state);prep(context,"hanged_man","food_given");JSONObject built=build(state,context);JSONArray checks=built.getJSONArray("observation_checkpoints");for(int i=0;i<checks.length();i++){JSONObject check=checks.getJSONObject(i);if(check.has("item_costs")){assertFalse(check.getJSONArray("item_costs").toString().contains("weird_takoyaki"));}}assertNull(action(built,"p3r.unlock.hanged_man.food_drink_and_promise"));}
    @Test public void currentInteractionFlagIsNotCopiedToFutureDates()throws Exception{JSONObject state=state("devil",7,25,true),context=context(state);prep(context,"devil","paid2");context.getJSONObject("unlock").getJSONObject("devil").put("lastPaymentDate",state.getInt("game_slot")/2-1).put("observations",o("{\"current.devil.payment_interaction_available\":true}"));JSONObject action=action(build(state,context),"p3r.unlock.devil.payment3");assertEquals(1,action.getJSONArray("slots").length());}
    @Test public void unknownStandaloneSunPreparationRetainsUnknownSlotCost()throws Exception{JSONObject state=state("sun",8,23,false),context=context(state);prep(context,"sun","pen_requested");JSONObject built=build(state,context);assertEquals(0,built.getJSONObject("rules").getJSONArray("actions").length());assertTrue(check(built,"preparation_slot_cost_unresolved"));}
    @Test public void staleCheckpointSuppressesAllActions()throws Exception{JSONObject state=state("emperor",4,27,false),context=context(state);context.getJSONObject("checkpoint").getJSONObject("date").put("ordinal",0);JSONObject built=build(state,context);assertEquals("unknown",built.getString("status"));assertEquals(0,built.getJSONObject("rules").getJSONArray("actions").length());}
    @Test public void unknownStageFormDefaultAndRealStageValues()throws Exception{JSONObject schema=adapter().preparationFormSchema(),devil=schema.getJSONObject("devil");assertEquals("unlock.devil.stage",devil.getString("stage_path"));JSONArray options=devil.getJSONArray("stage_options");assertTrue(options.getJSONObject(0).isNull("value"));assertTrue(options.toString().contains("paid2"));assertFalse(options.toString().contains("unlocked"));assertEquals(18,schema.length());}
    private void unknownRejected(JSONObject built,JSONObject action)throws Exception {try{PlannerEngine.transition(built.getJSONObject("rules"),built.getJSONObject("engine_snapshot"),action,new JSONObject());fail("Unknown numeric resource must not become a proven prerequisite");}catch(PlannerEngine.RuleViolation expected){assertEquals("unknown_requirement",expected.code);}}
    @Test public void unknownStatUpperBoundCannotOptimisticallySatisfyUnlockGate()throws Exception{JSONObject state=state("priestess",6,19,false);state.getJSONObject("facts").put("socialLinks.fortune.rank",interval(1)).put("socialStats.courage.raw",o("{\"low\":60,\"high\":null}"));JSONObject built=build(state,context(state));unknownRejected(built,action(built,"p3r.unlock.priestess"));}
    @Test public void unknownCashCannotPayFinalInstallment()throws Exception{JSONObject state=state("devil",7,25,true).put("cash",JSONObject.NULL),context=context(state);prep(context,"devil","paid2");context.getJSONObject("unlock").getJSONObject("devil").put("lastPaymentDate",state.getInt("game_slot")/2-1);exactGuards(context,state.getInt("game_slot"),"p3r.unlock.devil.payment3",o("{\"current.devil.payment_interaction_available\":true}"));JSONObject built=build(state,context);unknownRejected(built,action(built,"p3r.unlock.devil.payment3"));}
    @Test public void unknownFoodInventoryCannotBeConsumed()throws Exception{JSONObject state=state("moon",7,10,false),context=context(state);prep(context,"moon","rumor_heard");state.getJSONObject("facts").put("socialLinks.magician.rank",interval(3)).put("socialStats.charm.rank",interval(2));exactGuards(context,state.getInt("game_slot"),"p3r.unlock.moon.quiz_food_and_opening",o("{\"current.moon.opening_interaction_available\":true}"));JSONObject built=build(state,context);assertNotNull(action(built,"p3r.unlock.moon.quiz_food_and_opening"));unknownRejected(built,action(built,"p3r.unlock.moon.quiz_food_and_opening"));}
    @Test public void observedFoodIsChargedOnceAndRankZeroGuardPreventsReopening()throws Exception{JSONObject state=state("moon",7,10,false),context=context(state);prep(context,"moon","rumor_heard");state.getJSONObject("facts").put("socialLinks.magician.rank",interval(3)).put("socialStats.charm.rank",interval(2)).put("inventory.odd_morsel",interval(1));exactGuards(context,state.getInt("game_slot"),"p3r.unlock.moon.quiz_food_and_opening",o("{\"current.moon.opening_interaction_available\":true}"));JSONObject built=build(state,context),action=action(built,"p3r.unlock.moon.quiz_food_and_opening");JSONObject result=PlannerEngine.transition(built.getJSONObject("rules"),built.getJSONObject("engine_snapshot"),action,new JSONObject()).getJSONObject("state");assertEquals(0,result.getJSONObject("values").getJSONObject("inventory.odd_morsel").getInt("low"));assertEquals(0,action.getJSONObject("maximums").getInt("socialLinks.moon.rank"));assertTrue(built.getJSONObject("action_metadata").getJSONObject(action.getString("id")).getBoolean("requires_confirmed_quiz_success"));}

    @Test public void retainedPreparationUpperBoundAllowsObservedNextDayWithoutInventedHistory()throws Exception{JSONObject state=state("devil",7,25,true),context=context(state);prep(context,"devil","paid2");JSONObject prep=context.getJSONObject("unlock").getJSONObject("devil");prep.put("lastPossiblePrepOrdinal",state.getInt("game_slot")/2-1);exactGuards(context,state.getInt("game_slot"),"p3r.unlock.devil.payment3",o("{\"current.devil.payment_interaction_available\":true}"));String before=context.toString();JSONObject built=build(state,context);assertTrue(hasSlot(action(built,"p3r.unlock.devil.payment3"),state.getInt("game_slot")));assertEquals(before,context.toString());assertFalse(prep.has("lastPaymentDate"));}
    @Test public void futurePreparationBoundIsRejected()throws Exception{JSONObject state=state("devil",7,25,true),context=context(state);prep(context,"devil","paid2");context.getJSONObject("unlock").getJSONObject("devil").put("lastPossiblePrepOrdinal",state.getInt("game_slot")/2+1);try{build(state,context);fail("Future preparation upper bound must not enter forecasts");}catch(IllegalArgumentException expected){assertTrue(expected.getMessage().contains("Preparation date"));}}

}
